<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import type { ConfigRevisionCreateInput, ConfigRevisionSummary, ConfigTemplateCreateInput, ConfigTemplateSummary, NodeSummary } from '@cyberboard/types'
import StatusBadge from '@cyberboard/ui/components/StatusBadge.vue'
import StatePanel from '@cyberboard/ui/components/StatePanel.vue'
import { adminApi, getApiErrorMessage, normalizePage } from '../api'

const tab = ref<'templates' | 'revisions'>('templates')
const loading = ref(true)
const error = ref('')
const saving = ref(false)
const actionId = ref<string | null>(null)
const actionKind = ref<'publish' | 'rollback' | null>(null)
const formError = ref('')
const showForm = ref(false)
const editingId = ref<string | null>(null)
const templates = ref<ConfigTemplateSummary[]>([])
const revisions = ref<ConfigRevisionSummary[]>([])
const nodes = ref<NodeSummary[]>([])
const templateTotal = ref(0)
const revisionTotal = ref(0)
const templatePage = ref(1)
const revisionPage = ref(1)
const pageSize = 20
const form = reactive<ConfigTemplateCreateInput>({ name: '', description: '', coreType: 'sing-box', coreVersionRange: '>=1.11.0', status: 'draft' })
const revisionFilters = reactive({ search: '', status: '', nodeId: '' })
const showRevisionForm = ref(false)
const revisionFormError = ref('')
const revisionSaving = ref(false)
const revisionForm = reactive({ templateId: '', nodeId: '', generation: 1, coreVersion: '1.11.0', payload: '' })
const activeItems = computed(() => tab.value === 'templates' ? templates.value : revisions.value)

function resetForm() { Object.assign(form, { name: '', description: '', coreType: 'sing-box', coreVersionRange: '>=1.11.0', status: 'draft' }); editingId.value = null; showForm.value = false; formError.value = '' }
function resetRevisionForm() { Object.assign(revisionForm, { templateId: '', nodeId: '', generation: 1, coreVersion: '1.11.0', payload: JSON.stringify({ schema_version: 1, node_id: '', generation: 1, inbounds: [{ tag: 'vless-in', listen: '0.0.0.0', listen_port: 443, type: 'vless', transport: 'Tcp', tls: null, credential: 'None' }], outbounds: [], route: {} }, null, 2) }); revisionFormError.value = ''; showRevisionForm.value = false }
function editTemplate(item: ConfigTemplateSummary) { Object.assign(form, { name: item.name, description: item.description, coreType: item.coreType, coreVersionRange: item.coreVersionRange, status: item.status }); editingId.value = item.id; showForm.value = true; formError.value = '' }
async function loadTemplates() { const result = normalizePage(await adminApi.listConfigTemplates({ page: templatePage.value, pageSize }), templatePage.value, pageSize); templates.value = result.items; templateTotal.value = result.total }
async function loadNodes() { const first = normalizePage(await adminApi.listNodes({ page: 1, pageSize: 100 }), 1, 100); const later = await Promise.all(Array.from({ length: Math.max(0, Math.ceil(first.total / 100) - 1) }, (_, index) => adminApi.listNodes({ page: index + 2, pageSize: 100 }).then(result => normalizePage(result, index + 2, 100).items))); nodes.value = [...first.items, ...later.flat()] }
async function loadRevisions() { const result = normalizePage(await adminApi.listConfigRevisions({ page: revisionPage.value, pageSize, search: revisionFilters.search || undefined, status: revisionFilters.status || undefined, nodeId: revisionFilters.nodeId || undefined }), revisionPage.value, pageSize); revisions.value = result.items; revisionTotal.value = result.total }
async function load() { loading.value = true; error.value = ''; try { await Promise.all([loadTemplates(), loadRevisions(), loadNodes()]) } catch (cause) { error.value = getApiErrorMessage(cause) } finally { loading.value = false } }
async function saveTemplate() { saving.value = true; formError.value = ''; try { if (editingId.value) await adminApi.updateConfigTemplate(editingId.value, form); else await adminApi.createConfigTemplate(form); resetForm(); await loadTemplates() } catch (cause) { formError.value = getApiErrorMessage(cause) } finally { saving.value = false } }
function nodeFor(item: ConfigRevisionSummary) { return nodes.value.find(node => node.id === item.nodeId) }
function isDesiredRevision(item: ConfigRevisionSummary) { return nodeFor(item)?.desiredGeneration === item.generation }
function deploymentLabel(item: ConfigRevisionSummary) { switch (item.deploymentStatus) { case 'pending': return '待节点应用'; case 'applied': return '已应用'; case 'failed': return '失败'; case 'rolled_back': return '已回滚'; default: return '未发布' } }
function rollbackSourceLabel(item: ConfigRevisionSummary) { if (!item.rollbackOf) return ''; const source = revisions.value.find(revision => revision.id === item.rollbackOf); return source ? `回滚自 gen ${source.generation}` : '回滚版本' }
async function publish(item: ConfigRevisionSummary) { if (item.publishStatus !== 'draft') return; if (!window.confirm(`确认发布节点“${item.nodeName}”的 gen ${item.generation}？配置将签名并推送到节点，节点应用后才会生效。`)) return; actionId.value = item.id; actionKind.value = 'publish'; error.value = ''; try { await adminApi.publishConfigRevision(item.id, { expectedGeneration: item.generation }); await Promise.all([loadRevisions(), loadNodes()]) } catch (cause) { error.value = getApiErrorMessage(cause) } finally { actionId.value = null; actionKind.value = null } }
async function rollback(item: ConfigRevisionSummary) { if (!isDesiredRevision(item)) return; if (!window.confirm(`确认回滚节点“${item.nodeName}”当前 gen ${item.generation}？服务端会创建一个新版本并推送到节点，当前配置不会被原地修改。`)) return; actionId.value = item.id; actionKind.value = 'rollback'; error.value = ''; try { await adminApi.rollbackConfigRevision(item.id, { expectedGeneration: item.generation, reason: '管理员从控制面回滚' }); await Promise.all([loadRevisions(), loadNodes()]) } catch (cause) { error.value = getApiErrorMessage(cause) } finally { actionId.value = null; actionKind.value = null } }
async function createRevision() { revisionSaving.value = true; revisionFormError.value = ''; try { if (!revisionForm.templateId || !revisionForm.nodeId || revisionForm.generation < 1 || !revisionForm.coreVersion.trim()) throw new Error('请完整填写模板、节点、generation 和核心版本。'); const payload = JSON.parse(revisionForm.payload) as Record<string, unknown>; if (payload.node_id !== revisionForm.nodeId || payload.generation !== revisionForm.generation) throw new Error('JSON 中的 node_id 和 generation 必须与表单一致。'); const value: ConfigRevisionCreateInput = { templateId: revisionForm.templateId, nodeId: revisionForm.nodeId, generation: revisionForm.generation, coreVersion: revisionForm.coreVersion.trim(), payload }; await adminApi.createConfigRevision(value); resetRevisionForm(); tab.value = 'revisions'; await loadRevisions() } catch (cause) { revisionFormError.value = cause instanceof SyntaxError ? '配置 JSON 格式无效。' : getApiErrorMessage(cause) } finally { revisionSaving.value = false } }
watch(() => [tab.value, revisions.value.some(item => item.deploymentStatus === 'pending')] as const, ([activeTab, pending], _previous, onCleanup) => { if (activeTab !== 'revisions' || !pending) return; const timer = window.setInterval(() => { void loadRevisions().catch(cause => { error.value = getApiErrorMessage(cause) }) }, 3000); onCleanup(() => window.clearInterval(timer)) })
resetRevisionForm()
onMounted(load)
</script>

<template>
  <div class="page-heading"><div><p class="eyebrow">内核配置</p><h1>配置发布</h1><p>管理模板、版本、签名校验和节点发布状态。</p></div><div><button class="button button--secondary" type="button" :disabled="loading || Boolean(actionId)" @click="load">刷新</button><button v-if="tab === 'templates'" class="primary-button" type="button" :disabled="Boolean(actionId)" @click="showForm = true; editingId = null">+ 新建模板</button><button v-else class="primary-button" type="button" :disabled="Boolean(actionId)" @click="showRevisionForm = true">+ 新建版本</button></div></div>
  <StatePanel v-if="error" title="配置数据操作失败" :description="error" action-label="重试" @action="load" />
  <section v-if="showForm && tab === 'templates'" class="panel form-panel"><div class="panel-heading"><div><h2>{{ editingId ? '编辑配置模板' : '新建配置模板' }}</h2><p>核心版本范围会在发布前再次校验。</p></div><button class="button button--secondary" type="button" :disabled="saving" @click="resetForm">取消</button></div><form class="resource-form" @submit.prevent="saveTemplate"><label>名称<input v-model="form.name" required :disabled="saving" /></label><label>核心类型<input v-model="form.coreType" required :disabled="saving" /></label><label>版本范围<input v-model="form.coreVersionRange" required :disabled="saving" /></label><label>状态<select v-model="form.status" :disabled="saving"><option value="draft">草稿</option><option value="active">生效</option><option value="archived">归档</option></select></label><label class="form-span">描述<textarea v-model="form.description" rows="3" :disabled="saving" /></label><p v-if="formError" class="form-error" role="alert">{{ formError }}</p><button class="primary-button" type="submit" :disabled="saving">{{ saving ? '保存中…' : '保存模板' }}</button></form></section>
  <section v-if="showRevisionForm && tab === 'revisions'" class="panel form-panel"><div class="panel-heading"><div><h2>新建配置版本</h2><p>服务端会校验 ConfigProfile 并渲染 sing-box 配置。</p></div><button class="button button--secondary" type="button" :disabled="revisionSaving" @click="resetRevisionForm">取消</button></div><form class="resource-form" @submit.prevent="createRevision"><label>模板 ID<input v-model="revisionForm.templateId" required :disabled="revisionSaving" /></label><label>节点 ID<input v-model="revisionForm.nodeId" required :disabled="revisionSaving" /></label><label>Generation<input v-model.number="revisionForm.generation" type="number" min="1" required :disabled="revisionSaving" /></label><label>核心版本<input v-model="revisionForm.coreVersion" required :disabled="revisionSaving" /></label><label class="form-span">ConfigProfile JSON<textarea v-model="revisionForm.payload" class="mono" rows="14" required :disabled="revisionSaving" spellcheck="false" /></label><p v-if="revisionFormError" class="form-error" role="alert">{{ revisionFormError }}</p><button class="primary-button" type="submit" :disabled="revisionSaving">{{ revisionSaving ? '校验并创建中…' : '校验并创建版本' }}</button></form></section>
  <section class="panel"><div class="tabs"><button :class="['tab', tab === 'templates' && 'tab--active']" type="button" :disabled="Boolean(actionId)" @click="tab = 'templates'">配置模板</button><button :class="['tab', tab === 'revisions' && 'tab--active']" type="button" :disabled="Boolean(actionId)" @click="tab = 'revisions'">配置版本与发布</button></div><StatePanel v-if="loading" title="正在加载配置数据" description="正在读取模板、版本和节点发布状态。" /><template v-else-if="tab === 'templates'"><StatePanel v-if="!activeItems.length" title="暂无配置模板" description="控制面尚未返回配置模板。" /><div v-else class="table-wrap"><table><thead><tr><th>模板</th><th>核心</th><th>版本范围</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in templates" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ item.description }}</small></td><td>{{ item.coreType }}</td><td class="mono">{{ item.coreVersionRange }}</td><td><StatusBadge :status="item.status" /></td><td>{{ item.updatedAt }}</td><td><button class="row-action" type="button" :disabled="Boolean(actionId)" @click="editTemplate(item)">编辑</button></td></tr></tbody></table><div class="pagination"><button class="button button--secondary" :disabled="templatePage <= 1 || Boolean(actionId)" @click="templatePage--; loadTemplates()">上一页</button><span>第 {{ templatePage }} 页 · 共 {{ templateTotal }} 条</span><button class="button button--secondary" :disabled="templatePage * pageSize >= templateTotal || Boolean(actionId)" @click="templatePage++; loadTemplates()">下一页</button></div></div></template><template v-else><div class="toolbar"><input v-model="revisionFilters.search" class="search-input" placeholder="搜索节点、hash 或版本" @keyup.enter="revisionPage = 1; loadRevisions()" /><select v-model="revisionFilters.status" aria-label="发布状态" @change="revisionPage = 1; loadRevisions()"><option value="">全部发布状态</option><option value="draft">草稿</option><option value="published">已发布</option><option value="rolled_back">已回滚</option></select>
<select v-model="revisionFilters.nodeId" aria-label="节点" @change="revisionPage = 1; loadRevisions()"><option value="">全部节点</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option></select></div><StatePanel v-if="!revisions.length" title="暂无配置版本" description="控制面尚未返回配置版本或发布记录。" /><div v-else class="table-wrap"><table><thead><tr><th>版本</th><th>目标节点</th><th>generation</th><th>核心</th><th>hash / 签名</th><th>校验</th><th>发布结果</th><th>部署状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in revisions" :key="item.id"><td class="mono">{{ item.id }}<small>{{ item.createdAt }}</small><small v-if="item.rollbackOf">{{ rollbackSourceLabel(item) }}</small></td><td>{{ item.nodeName }}<small class="mono">{{ item.nodeId }}</small></td><td class="mono">{{ item.generation }}</td><td>{{ item.coreVersion }}</td><td class="mono">{{ item.contentHash }}<small>签名：{{ item.signatureStatus }}</small></td><td><StatusBadge :status="item.validationStatus" /></td><td><StatusBadge :status="item.publishStatus" /><small v-if="item.failureReason" class="form-error">{{ item.failureReason }}</small></td><td><StatusBadge :status="item.deploymentStatus ?? 'not_published'" :label="deploymentLabel(item)" /><small v-if="item.deploymentStatus === 'failed' || item.deploymentStatus === 'rolled_back'" class="form-error">{{ [item.deploymentErrorCode, item.deploymentErrorMessage].filter(Boolean).join('：') }}</small></td><td><button v-if="item.publishStatus === 'draft'" class="row-action" type="button" :disabled="Boolean(actionId)" @click="publish(item)">{{ actionId === item.id && actionKind === 'publish' ? '发布中…' : '发布' }}</button><button v-if="isDesiredRevision(item)" class="row-action" type="button" :disabled="Boolean(actionId)" @click="rollback(item)">{{ actionId === item.id && actionKind === 'rollback' ? '回滚中…' : '回滚' }}</button></td></tr></tbody></table><div class="pagination"><button class="button button--secondary" :disabled="revisionPage <= 1 || Boolean(actionId)" @click="revisionPage--; loadRevisions()">上一页</button><span>第 {{ revisionPage }} 页 · 共 {{ revisionTotal }} 条</span><button class="button button--secondary" :disabled="revisionPage * pageSize >= revisionTotal || Boolean(actionId)" @click="revisionPage++; loadRevisions()">下一页</button></div></div></template></section>
</template>
